{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/charts",
  "data": [
    {
      "name": "position",
      "type": "'top' | 'right' | 'bottom' | 'left'",
      "description": "Physical plot edge on which to render the axis.",
      "required": true
    },
    {
      "name": "tickCount",
      "type": "number",
      "description": "Approximate continuous-scale tick count. d3 chooses the final values.",
      "default": "5"
    },
    {
      "name": "maxTicks",
      "type": "number",
      "description": "Maximum displayed label count. Labels are evenly skipped when the generated set is larger."
    },
    {
      "name": "tickFormat",
      "type": "(value: unknown) => string",
      "description": "Formats each retained tick. When omitted, continuous scales use d3 formatting and band scales use their category strings."
    },
    {
      "name": "truncate",
      "type": "number",
      "description": "Maximum content characters retained before an ellipsis is appended. User-perceived characters remain intact."
    },
    {
      "name": "animated",
      "type": "boolean",
      "description": "Whether tick position and visibility changes use the built-in transition.",
      "default": "true"
    },
    {
      "name": "showAxisLine",
      "type": "boolean",
      "description": "Whether to draw the edge line. Tick marks force the line on so they remain grounded.",
      "default": "true for bottom; false for top, right, and left"
    },
    {
      "name": "showTicks",
      "type": "boolean",
      "description": "Whether to draw an outward mark at each retained tick.",
      "default": "false"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
